INSERT INTO experiences (lang, slug, title, subtitle, headline, description, `includes`, price, priceLabel, duration, ctaText, seoText, imageUrl, galleryImages, isActive, sortOrder) VALUES ('de', 'picknick-im-wald', 'Picknick im Wald', 'Genuss unter freiem Himmel – direkt aus unserem Haus in die Natur', 'Ihr Picknick zwischen Bäumen und Vogelgesang', 'Manche Momente schmecken draußen einfach besser. Unser Waldpicknick ist genau für diese Momente gemacht: ein liebevoll gepackter Picknickkorb, eine Flasche gekühlter Sekt und ein ruhiger Platz zwischen den Bäumen des Wiehengebirges.

Sie wählen, ob wir Ihren Korb mit einem herzhaften Frühstück oder einem kalten Lunch bestücken – beides frisch zubereitet aus unserer Küche. Dazu eine Flasche Sekt für zwei Personen, Geschirr und eine Decke. Alles, was Sie brauchen, ist ein freier Vormittag und Lust auf frische Luft.

Das Picknick kann zu jeder Übernachtung im Waldhotel Bad Essen dazu gebucht werden. Ob als Überraschung, als gemeinsamer Start in den Tag oder als entspannter Mittag im Grünen – dieses Erlebnis macht Ihren Aufenthalt zu etwas Besonderem.', '["Picknickkorb für 2 Personen","Frühstück oder kalter Lunch nach Wahl","1 Flasche Sekt (gekühlt)","Geschirr, Besteck und Picknickdecke","Empfehlung für die schönsten Plätze in der Umgebung"]', 'ab 54,00 €', 'pro Picknick für 2 Personen · zu jeder Übernachtung buchbar', 'Zu jeder Übernachtung buchbar', 'Jetzt Picknick anfragen', 'Ein Picknick im Wald gehört zu den schönsten Erlebnissen, die Bad Essen zu bieten hat. Das Waldhotel Bad Essen liegt direkt am Wiehengebirge und bietet den idealen Ausgangspunkt für ein Picknick in der Natur. Ob als romantisches Erlebnis zu zweit, als Ergänzung zum Kurzurlaub oder als besonderer Moment während einer Wanderung – unser Picknickkorb mit Sekt macht jeden Aufenthalt unvergesslich. Genießen Sie frische Luft, regionale Köstlichkeiten und die Stille des Waldes.', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663365901872/gP4ek7BMjABi6Nex8zFehy/picknick-wald-1-devMVvDTFps7AW2comDxSd.webp', '["https://d2xsxph8kpxj0f.cloudfront.net/310519663365901872/gP4ek7BMjABi6Nex8zFehy/picknick-wald-1-devMVvDTFps7AW2comDxSd.webp","https://d2xsxph8kpxj0f.cloudfront.net/310519663365901872/gP4ek7BMjABi6Nex8zFehy/picknick-wald-2-ioXg2dD3hycw6ocTD9fMsG.webp","https://d2xsxph8kpxj0f.cloudfront.net/310519663365901872/gP4ek7BMjABi6Nex8zFehy/picknick-wald-3-WrDXX5j77Jq57w76dvtDp2.webp","https://d2xsxph8kpxj0f.cloudfront.net/310519663365901872/gP4ek7BMjABi6Nex8zFehy/picknick-wald-4-e267ug7xPua2azZP4hjV5j.webp"]', true, 1);

